import { createZoomClient, parseZoomRateLimit, isRecord, fieldString, fieldValue, queryValue, assertZoomRawSegment, optionalZoomSegment } from "./http";
import { assertNoTraversalSegment } from "../../_shared/jobboard";

export type DepthPathParam = { name: string; aliases: string[] };
export type DepthOpSpec = {
  action: string;
  tool: string;
  method: "GET" | "POST" | "PATCH" | "PUT" | "DELETE";
  path: string;
  title: string;
  description: string;
  pathParams: DepthPathParam[];
  query: string[];
  body: string[];
  required: string[];
  sample: Record<string, unknown>;
  defaults: Record<string, string>;
  fileField?: string;
  passthrough: boolean;
};

const SKIP_KEYS = new Set(["accessToken", "fetch", "validated"]);

function aliasesFor(spec: DepthOpSpec, name: string): string[] {
  const pathParam = spec.pathParams.find((item) => item.name === name);
  if (pathParam) return pathParam.aliases;
  return [name, name.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`).replace(/^_/, "")];
}

export function validateDepthInput(spec: DepthOpSpec, input: unknown): Record<string, unknown> {
  if (!isRecord(input)) throw new Error(`${spec.action} input must be an object`);
  const validated: Record<string, unknown> = {};
  for (const param of spec.pathParams) {
    // SEC-PATH-2b: only an omitted value takes the documented default; a
    // present "" or whitespace value is rejected instead of becoming "me".
    const fallback = spec.defaults[param.name];
    const value = optionalZoomSegment(input, param.name, ...param.aliases) ?? fallback;
    if (spec.required.includes(param.name) && !value) throw new Error(`${param.name} is required`);
    if (value) validated[param.name] = value;
  }
  for (const key of [...spec.query, ...spec.body]) {
    const value = fieldValue(input, ...aliasesFor(spec, key));
    if (value !== undefined) validated[key] = value;
  }
  for (const key of spec.required) {
    if (validated[key] !== undefined && validated[key] !== "") continue;
    const value = fieldValue(input, ...aliasesFor(spec, key));
    if (value === undefined || value === "") throw new Error(`${key} is required`);
    validated[key] = value;
  }
  if (spec.fileField) {
    const file = fieldValue(input, spec.fileField);
    if (file !== undefined) validated[spec.fileField] = file;
  }
  return validated;
}

// SEC-PATH-2: Zoom path values can be raw base64 UUIDs, so "/" is encoded rather
// than rejected; the encoded segment then passes the shared no-traversal guard,
// which rejects "." and ".." (encodeURIComponent leaves them intact).
function encodePathValue(value: string, name: string): string {
  // SEC-PATH-2b: guard the raw value before encoding (" " was sent as %20).
  return assertNoTraversalSegment(encodeURIComponent(assertZoomRawSegment(value, name)), name);
}

function buildPath(spec: DepthOpSpec, validated: Record<string, unknown>): string {
  return spec.path.replace(/\{([a-zA-Z0-9_]+)\}/g, (_match, name: string) => {
    const value = validated[name];
    if (typeof value !== "string" || value.length === 0) throw new Error(`${name} is required`);
    return encodePathValue(value, name);
  });
}

function buildQuery(spec: DepthOpSpec, input: Record<string, unknown>, validated: Record<string, unknown>): string {
  const params = new URLSearchParams();
  for (const key of spec.query) {
    const raw = validated[key] ?? fieldValue(input, ...aliasesFor(spec, key));
    const value = queryValue(raw);
    if (value !== undefined) params.set(key, value);
  }
  const query = params.toString();
  return query ? `?${query}` : "";
}

function buildJsonBody(spec: DepthOpSpec, input: Record<string, unknown>, validated: Record<string, unknown>): Record<string, unknown> | undefined {
  if (spec.method === "GET") return undefined;
  const body: Record<string, unknown> = {};
  const used = new Set<string>([...spec.pathParams.map((item) => item.name), ...spec.query, spec.fileField ?? "", ...SKIP_KEYS]);
  for (const key of spec.body) {
    if (validated[key] !== undefined) body[key] = validated[key];
  }
  if (spec.passthrough) {
    for (const [key, value] of Object.entries(input)) {
      if (used.has(key) || spec.body.includes(key) || spec.query.includes(key)) continue;
      if (spec.pathParams.some((item) => item.aliases.includes(key) || item.name === key)) continue;
      body[key] = value;
    }
  }
  return Object.keys(body).length > 0 ? body : undefined;
}

async function executeDepthOp(spec: DepthOpSpec, input: Record<string, unknown>, validated: Record<string, unknown>): Promise<Record<string, unknown>> {
  const client = createZoomClient({
    accessToken: String(input.accessToken),
    fetch: typeof input.fetch === "function" ? input.fetch as typeof fetch : undefined,
    operation: spec.action,
  });
  const path = `${buildPath(spec, validated)}${buildQuery(spec, input, validated)}`;
  const init: RequestInit = { method: spec.method };
  if (spec.fileField) {
    const file = validated[spec.fileField];
    const form = new FormData();
    const filename = fieldString(input, "file_name", "filename") ?? "whiteboard.bin";
    if (typeof Blob !== "undefined" && file instanceof Blob) form.append(spec.fileField, file, filename);
    else form.append(spec.fileField, new Blob([String(file ?? "")], { type: "application/octet-stream" }), filename);
    init.body = form;
  } else {
    const body = buildJsonBody(spec, input, validated);
    if (body && spec.method !== "GET") init.body = JSON.stringify(body);
  }
  const response = await client.fetchJSON(path, init);
  const rateLimit = parseZoomRateLimit(response.status, response.headers);
  if (rateLimit.limited) {
    throw { ok: false, code: "CONNECTOR_RATE_LIMITED", message: "Zoom rate limit exceeded.", retryAfterSeconds: rateLimit.retryAfterSeconds };
  }
  if (response.status === 200 || response.status === 201 || response.status === 202 || response.status === 204) {
    return { connector: "zoom", action: spec.action, source: "connector", data: response.body };
  }
  throw { ok: false, code: "CONNECTOR_UPSTREAM_ERROR", message: `Zoom rejected the ${spec.action} request.` };
}

export function runDepthOp(spec: DepthOpSpec, input: unknown): Record<string, unknown> | Promise<Record<string, unknown>> {
  const validated = validateDepthInput(spec, input);
  if (isRecord(input) && typeof input.accessToken === "string") {
    return executeDepthOp(spec, input, validated);
  }
  return { connector: "zoom", action: spec.action, source: "connector", validated };
}

